// =====================================================================
// GAME_DATA（種族配列）＋ ja_JP.lang.js（名前）を、engine.js / ui.js / net.js が
// これまで通り使える形（GAME_DATA.species / GAME_DATA.moves などを持つオブジェクト）
// に変換する処理。
// =====================================================================
(function () {
  // ---- 言語ファイル（key=value形式のテキスト）を同期的に読み込んでパースする ----
  function loadLangFileSync(path) {
    const map = {};
    try {
      const xhr = new XMLHttpRequest();
      xhr.open('GET', path, false); // 同期読み込み（このスクリプトの実行中に完了させるため）
      xhr.send(null);
      if (xhr.status !== 0 && xhr.status !== 200) return map;
      const text = xhr.responseText || '';
      const lines = text.split(/\r?\n/);
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line || line.startsWith('//') || line.startsWith('#')) continue;
        const eqIdx = line.indexOf('=');
        if (eqIdx < 0) continue;
        const key = line.slice(0, eqIdx).trim();
        const value = line.slice(eqIdx + 1).trim();
        map[key] = value;
      }
    } catch (e) {
      console.warn('[gamedata] ja_JP.lang.js の読み込みに失敗しました。名前が正しく表示されない場合があります。', e);
    }
    return map;
  }

  // "entity.pokemon:p3" → 3 のように、キーからポケモンIDを取り出す
  function getPokemonNameMap(langMap) {
    const names = {};
    const prefix = 'entity.pokemon:p';
    const suffix = '.name';
    for (const key in langMap) {
      if (!key.startsWith(prefix)) continue;
      if (!key.endsWith(suffix)) continue;
      const idStr = key.slice(prefix.length, key.length - suffix.length);
      const id = parseInt(idStr, 10);
      if (!isNaN(id)) names[id] = langMap[key];
    }
    return names;
  }

  // typeNames（{0:"",1:"むし",2:"あく",...}）と typeKeyToJp（{'dark':'あく',...}）から
  // 「タイプ番号 → typeKey（'dark'等）」の対応表を作る。
  function buildTypeIdToKeyMap() {
    const idToKey = {};
    const jpToKey = {};
    for (const key in GAME_TYPE_KEY_TO_JP) {
      jpToKey[GAME_TYPE_KEY_TO_JP[key]] = key;
    }
    for (const idStr in GAME_TYPE_NAMES) {
      const jp = GAME_TYPE_NAMES[idStr];
      if (jp && jpToKey[jp]) {
        idToKey[parseInt(idStr, 10)] = jpToKey[jp];
      }
    }
    return idToKey; // 例: {1:'bug', 2:'dark', ..., 10:'grass', ...}  (0番はタイプなしなので含まれない)
  }

  // GAME_DATA配列の1匹分を、既存互換の species オブジェクトに変換する
  function convertOneSpecies(entry, typeIdToKey, nameMap) {
    // entry = [ id, [不使用], [不使用, baseExp], [[[type1,type2,[abilities],hp,atk,def,spa,spd,spe]]], evolutions, levelMoves, [不使用] ]
    const id = entry[0];
    const baseExpInfo = entry[2] || [];
    const baseExp = baseExpInfo.length > 1 ? baseExpInfo[1] : 0;
    const statsBlock = entry[3] && entry[3][0] && entry[3][0][0] ? entry[3][0][0] : null;
    if (!statsBlock) {
      console.warn('[gamedata] GAME_DATA: ID ' + id + ' のステータス情報が不正です。スキップします。');
      return null;
    }
    const type1Id = statsBlock[0];
    const type2Id = statsBlock[1];
    const abilities = statsBlock[2] || [];
    const hp = statsBlock[3];
    const atk = statsBlock[4];
    const def = statsBlock[5];
    const spa = statsBlock[6];
    const spd = statsBlock[7];
    const spe = statsBlock[8];

    const type1 = typeIdToKey[type1Id] || null;
    const type2 = (type2Id && type2Id !== 0) ? (typeIdToKey[type2Id] || null) : null;

    const evolutions = entry[4] || [];
    const levelMoves = entry[5] || [];

    const name = nameMap[id] || ('？？？(' + id + ')');

    return {
      id: id,
      name: name,
      type1: type1,
      type2: type2,
      abilities: abilities,
      baseStats: { hp: hp, atk: atk, def: def, spa: spa, spd: spd, spe: spe },
      levelMoves: levelMoves,
      evolutions: evolutions,
      baseExp: baseExp,
    };
  }

  function buildGameData() {
    const langMap = loadLangFileSync('ja_JP.lang.js');
    const nameMap = getPokemonNameMap(langMap);
    const typeIdToKey = buildTypeIdToKeyMap();

    const speciesObj = {};
    let converted = 0;
    for (let i = 0; i < GAME_DATA.length; i++) {
      const sp = convertOneSpecies(GAME_DATA[i], typeIdToKey, nameMap);
      if (!sp) continue;
      speciesObj[String(sp.id)] = sp;
      converted++;
    }
    console.log('[gamedata] GAME_DATA配列から ' + converted + ' 件のポケモンデータを読み込みました。');

    // GAME_DATA を、engine.js / ui.js / net.js がこれまで通り使える形に置き換える。
    GAME_DATA = {
      species: speciesObj,
      moves: GAME_MOVES,
      typeChart: GAME_TYPE_CHART,
      abilityNames: GAME_ABILITY_NAMES,
      typeNames: GAME_TYPE_NAMES,
      typeKeyToJp: GAME_TYPE_KEY_TO_JP,
      natureDesc: GAME_NATURE_DESC,
    };
  }

  buildGameData();
})();
